provider = params["provider"]
problem = ""
candidates = []
settings = bk_read_json(BK_SETTINGS) or {}
ledger = bk_read_json(BK_MAIL + "/" + provider + ".json") or {}
now = datetime.datetime.now(datetime.timezone.utc)
# The first run looks back a day; after that only emails the ledger hasn't seen are picked up.
since_at = mail_when(ledger.get("since")) or (now - datetime.timedelta(hours=MAIL_FIRST_RUN_HOURS))
since = since_at.replace(microsecond=0).isoformat()

if not settings:
    problem = "Bookkeeping isn't set up yet."
else:
    seen = ledger.get("seen") or {}
    for m in mail_recent(provider):
        if m["id"] in seen:
            continue
        when = mail_when(m["received"])
        if when and when < since_at:
            continue
        candidates.append(m)
    # Oldest first, and a bounded batch per run; the rest are picked up by the next run.
    candidates = sorted(candidates, key=lambda m: m["received"])[:MAIL_PER_RUN]

# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_add_business_days(day, n):
    d = day
    while n > 0:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d


def bk_reviewer(settings, client):
    return (client or {}).get("reviewer_id") or (settings or {}).get("reviewer_id")


def bk_exceptions_owner(settings, client):
    return (settings or {}).get("exceptions_owner_id") or bk_reviewer(settings, client)


# ── bookkeeping kit: mailbox adapter (inlined into email-intake nodes by gen-ext.js) ──
# Reads the automation owner's own mailbox: Outlook through m365-mail-read, Gmail through google-workspace-gmail.
# Read-only: nothing in the mailbox is changed, so emails that aren't bills stay exactly as they were.
import base64
import html

MAIL_SERVER = {"outlook": "m365-mail-read", "gmail": "google-workspace-gmail"}
MAIL_FIRST_RUN_HOURS = 24
MAIL_PER_RUN = 10


def mail_call(provider, tool, **args):
    return api.connectors.invoke(server=MAIL_SERVER[provider], tool=tool, args=args)


def mail_body(provider, msg_id, fallback=""):
    """The email's text: Outlook's full body (HTML reduced to text); for Gmail the snippet, all its connector returns."""
    if provider != "outlook":
        return fallback
    msg = mail_call(provider, "get_email", id=msg_id)
    body = msg.get("body") if isinstance(msg, dict) else None
    text = str(body.get("content") or "") if isinstance(body, dict) else ""
    if "<" in text and ">" in text:
        text = re.sub(r"(?is)<(script|style)[^>]*>.*?</(script|style)>", " ", text)
        text = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</tr>|</li>|</h[1-6]>", "\n", text)
        text = html.unescape(re.sub(r"<[^>]+>", " ", text))
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text).strip()
    return text[:8000] or fallback


def mail_sender(value):
    """The address in "Name <address>" (or a bare address), lower-cased."""
    m = re.search(r"[\w.+'-]+@[\w-]+(\.[\w-]+)+", str(value or ""))
    return m.group(0).lower() if m else ""


def mail_download(provider, msg_id, att, dest):
    """Save one attachment's bytes to the scratch path `dest`; returns the size."""
    tool = "get_email_attachment" if provider == "outlook" else "get_attachment"
    res = mail_call(provider, tool, messageId=msg_id, attachmentId=att["id"])
    data = base64.b64decode(str((res or {}).get("contentBase64") or "")) if isinstance(res, dict) else b""
    if not data:
        raise RuntimeError("the attachment came back empty")
    with open(dest, "wb") as fh:
        fh.write(data)
    return len(data)


